  pricingAfterTrialTitle: "14 günlük denemeden sonra ne değişir",
  pricingAfterTrialBody: "Dramatik bir şey yok. Giriş yapmış kalırsınız, veriniz güvende, her özellik hala orada. Free gerçekten kullanılabilir — deneme bittiğinde sadece bu sınırlar geri gelir:",
  pricingAfterTrialCap1: "Ayda 200 satış kaydı",
  pricingAfterTrialCap2: "Ayda 100 gider kaydı",
  pricingAfterTrialCap3: "Ayda 30 fiş OCR taraması",
  pricingAfterTrialCap4: "Günde 30 AI Copilot sorusu",
  pricingAfterTrialCap5: "Aynı anda en fazla 5 aktif AI insights",
  pricingAfterTrialCap6: "1 vertical modül (birini seç)",
  pricingAfterTrialCap7: "90 gün tam geçmiş (eski salt okunur)",
  pricingAfterTrialCap8: "1 işletme, 1 kullanıcı",
  pricingAfterTrialClosing: "Denemeyi başlatmak için kart gerekmez — kayıt olduğunuzda otomatik çalışır. Founding fiyatını (Starter 129 kr/ay veya Pro 249 kr/ay) ömür boyu korumak için \"Founding fiyatını kilitle\"yi tıklarsanız kart gerekir. Aksi takdirde deneme biter ve Free'ye düşersiniz.",
  faqHeading: "Sık sorulan sorular",
  faqQ1: "14 günlük denemem bittiğinde ne olur?",
  faqA1: "Kilitleyip kilitlemediğinize bağlı. Kilitlemediyseniz: otomatik olarak Free'ye düşersiniz. Her özellik kalır, sadece kullanım sınırları geri gelir, verileriniz dokunulmaz, asla ücretlendirilmezsiniz. Kilitlediyseniz: 15. gün ve sonra her ay founding fiyatı kartınızdan tahsil edilir, ömür boyu kilitlidir. Her halükarda: sürpriz yok.",
  faqQ2: "Neden Free her özelliğe sahip, sadece sınırlı?",
  faqA2: "Çünkü özellik kilidi küçük dükkanlara bir vergidir. Ayda sadece 50 satış yapan bir yan iş sahibi AI insights'tan kilitlenmemeli — onlar yoğun bir dükkandan DAHA ÇOK insight'a ihtiyaç duyar. Sınırlar, Free kullanıcılarının tam değer aldığı ve sadece Free'nin yetmediği zaman yükselttiği anlamına gelir.",
  faqQ3: "Founding üye fiyatı nasıl çalışır?",
  faqA3: "İlk 100 Pro abonesi abone kaldıkları sürece 249 kr/ay'ı kilitler — düzenli Pro fiyatımız 349 kr/ay olduğunda bile. İptal edip tekrar katılırsanız? Düzenli fiyat ödersiniz. Kesintisiz abone kalırsanız? Kilitlisiniz.",
  faqQ4: "Birden çok şubeli zincir işletiyorum — ne uyar?",
  faqA4: "Pro 3 lokasyona kadar kapsar. Daha fazlası için: hello@bonbox.dk'ya e-posta gönderin, 1 iş günü içinde özel Business planı teklifi sunarız.",
  faqQ5: "BonBox bir Dinero alternatifi mi?",
  faqA5: "Hayır. BonBox kayıtlı bir dijital muhasebe sistemi değil, yani mevcut sistemini korursun — ve ona ödemeye devam edersin. BonBox günlük işi yapar: fakturaer, müşteriler, kilometre, OCR ile okunan fişler ve banka eşleştirme, böylece sonradan düzeltilecek daha az şey kalır. Resmî beyanlar, MOMS-angivelse ve årsregnskab, revisor'unla birlikte yine kendi muhasebe sisteminde yapılır.",
  faqQ6: "MOMS ne olacak?",
  faqA6: "Gösterilen tüm fiyatlar MOMS hariçtir. Danimarka işletmeleri otomatik olarak %25 MOMS ile faturalandırılır. Geçerli MOMS numarasına sahip AB işletmeleri reverse-charge yapılır.",
  faqQ7: "Her zaman iptal edebilir miyim?",
  faqA7: "Evet. Sözleşme yok, bildirim süresi yok. Mevcut faturalama döneminin sonuna kadar erişiminizi korur ve istediğiniz zaman tüm verilerinizi dışa aktarabilirsiniz.",
  faqQ8: "Verilerim güvende mi?",
  faqA8: "EU-barındırılan, depoda ve transit'te şifrelenmiş, GDPR uyumlu, asla satılmaz, pazarlamacılarla asla paylaşılmaz, AI modellerini eğitmek için asla kullanılmaz. Tam dışa aktarım ve silme araçları dahili.",
  pricingTrademarkNotice: "Dinero, Billy, e-conomic, MobilePay ve Dankort ilgili sahiplerinin ticari markalarıdır. BonBox bu şirketlerin hiçbirine bağlı veya tarafından onaylanmış değildir. Atıflar, nominative fair use kapsamında birlikte çalışabilirlik ve karşılaştırma amacıyla yapılmıştır.",
  closerPromptTitle: "Sizin için kim kapatıyor?",
  closerPromptBody: "Çoğu restoranda front-of-house (garson / barmen) vardiya sonunda kapatır — sahip değil. Kapatan kişiyi söyleyin ki günlük kapanış onayını o alsın. (Sahip yine de konsolide PDF'i alır.)",
