  smartImportSupplierGateCta: "Yükselt",
  featStarterCloseGuard: "Kapanışta canlı anomali koruması — yanlış okunan tutarı kaydedilmeden yakalar",
  faqQ9: "BonBox kayıtlı bir dijital muhasebe sistemi mi?",
  faqA9: "Hayır — ve bunu açıkça söylüyoruz. BonBox bir faturalama + veri toplama aracıdır (kasserapport OCR, faktura, kilometre, günlük kapanış PDF'i). 2024 Bogføringsloven kapsamında Erhvervsstyrelsen'de dijital bogføringssystem olarak kayıtlı değildir. İşletmen yasal olarak kayıtlı bir sistemde defter tutmak zorundaysa bunun için Dinero / Billy / e-conomic kullanmaya devam et — BonBox onun yanında durur ve temiz dışa aktarımlar besler. revisor'unun yerini almaya çalışmıyoruz; ona verdiğin girdiyi ucuzlatıyoruz.",
  faqQ10: "Revisor'umun kendi girişi olması gerekiyor mu?",
  faqQ11: "Personel vardiya otopilotu nasıl çalışır?",
  faqA11: "Pro özelliği. Personel → Vardiya → Otopilotu çalıştır. BonBox son 8 haftanın gün bazlı cirosunu okur, şehrinin 7 günlük hava tahminiyle birleştirir ve gelecek hafta için tahmini talebi en düşük işçilik maliyetiyle karşılayan bir vardiya planı önerir. DK iş hukukuna (6+ saatlik vardiyalarda 45 dk mola, günlük 11 saat dinlenme, haftalık saat sınırları) ve her personelin uygunluğuna uyar. Öneriyi vardiya vardiya gözden geçirir, istediğini düzenler, sonra Uygula'ya dokunursun. Kopenhag'daki çoğu kafe, model 2-3 haftalık veriyle öğrendikten sonra ücretlerde %5–10 tasarruf ediyor.",
  faqQ12: "Banka mutabakatı nasıl çalışır?",
  faqA12: "Bugün: netbank CSV'ni yüklüyorsun (Danske Bank, Nordea, Jyske, Spar Nord veya Lunar'da 2 tık) ve BonBox ödemeleri açık faktura'larınla güven seviyelerine göre otomatik eşleştiriyor. Yüksek güvenli eşleşmeleri tek dokunuşla onaylarsın; belirsiz olanlar defterlere değil bir inceleme kutusuna düşer. Doğrudan PSD2 senkronizasyonu (Aiia / Salt Edge) ortaklığı kapattığımızda yol haritasında; CSV yolu yedek olarak kalacak. Gerçekten bağlanana kadar açmayacağız — sahte 'Bağlandı' etiketi yok.",
