  customersStep2Title: "2. Bireysel müşteriler — CVR yok",
  customersStep2Body: "Privatpersoner için B2B anahtarını kapat. Yine de bir ad ve e-posta ya da telefondan en az biri gerekiyor, ki faktura ulaşacak bir yer bulsun.",
