  landingFaqTag: "Sorular",
  landingFaqTitle: "Kayıt olmadan önce sorulanlar.",
  landingFaq1Q: "POS'umla çalışır mı?",
  landingFaq1A: "BonBox POS'unun yerini almaz — ondan çıkanı okur. Herhangi bir telefonla kasserapport'un fotoğrafını çek, BonBox sayıları çıkarır. Hangi kasayı kullandığından bağımsız çalışır, kağıt kasserapport dahil. (Marka entegrasyonumuz yok — Z-raporunu OCR ile okuruz, yani onu yazdıran her POS çalışır.)",
  landingFaq2Q: "Yine de muhasebeciye ihtiyacım var mı?",
  landingFaq2A2: "Evet, årsregnskab ve SKAT bildirimleri için. BonBox aylık rutini üstlenir (satışlar, faktura, banka eşleştirme, OCR fişler, MOMS takibi), böylece revisor'un sana yılda bir kez ihtiyaç duyar.",
  landingFaq3Q: "AI bir kasserapport'u yanlış okursa?",
  landingFaq3A: "Okunan her fiş düzenlenebilir — AI önerir, sen onaylarsın. Düşük güvenli eşleşmeler defterlere değil, İnceleme kutusuna gider. Sen dokunmadan hiçbir şey 'kesin'e geçmez. Ayrıca 10 yıllık denetim kaydı her değişikliği tutar.",
  landingFaq4Q: "Verilerim nerede tutuluyor?",
  landingFaq5Q: "Kayıt için CVR gerekli mi?",
  landingFaq5A: "Hayır. E-posta ile kaydol. CVR doğrulamalı müşteriler + fakturaer'de otomatik doldurma istediğinde CVR'yi sonra ekle. CVR'si olmayan serbest çalışanlar da sorunsuz — her müşteride 'Privatperson' seçeneğini aç.",
  landingFaq6Q: "14 günlük deneme bitince ne olur?",
